-- The initial released schema is the complete current application schema.
-- Migrations are immutable after release; future changes add forward versions.
-- +goose Up
CREATE TABLE registration_grants(token_hash BLOB PRIMARY KEY,expires_at INTEGER NOT NULL,created_at INTEGER NOT NULL,purpose TEXT NOT NULL DEFAULT 'setup',credential_generation INTEGER NOT NULL DEFAULT 0);
CREATE TABLE administrator(id INTEGER PRIMARY KEY CHECK(id=1),registration_record BLOB NOT NULL,profile_generation INTEGER NOT NULL,credential_generation INTEGER NOT NULL DEFAULT 1,created_at INTEGER NOT NULL);
CREATE TABLE opaque_profile(singleton INTEGER PRIMARY KEY CHECK(singleton=1),profile_generation INTEGER NOT NULL,key_generation TEXT NOT NULL,profile TEXT NOT NULL);
CREATE TABLE repository_key_store(singleton INTEGER PRIMARY KEY CHECK(singleton=1),verifier BLOB NOT NULL);
CREATE TABLE repository_keys(id TEXT PRIMARY KEY,name TEXT NOT NULL,algorithm TEXT NOT NULL,bits INTEGER NOT NULL,fingerprint TEXT NOT NULL,public_key TEXT NOT NULL,ciphertext BLOB NOT NULL,created_at INTEGER NOT NULL);
CREATE TABLE projects(id TEXT PRIMARY KEY,name TEXT NOT NULL,remote_url TEXT NOT NULL,created_at INTEGER NOT NULL,last_fetched INTEGER,warning TEXT NOT NULL DEFAULT '');
CREATE TABLE project_refs(project_id TEXT NOT NULL REFERENCES projects(id) ON DELETE CASCADE,kind TEXT NOT NULL,name TEXT NOT NULL,commit_id TEXT NOT NULL,PRIMARY KEY(project_id,kind,name));
CREATE TABLE project_refresh_journal(project_id TEXT PRIMARY KEY);
CREATE TABLE project_ssh_keys(project_id TEXT PRIMARY KEY REFERENCES projects(id) ON DELETE CASCADE,key_id TEXT NOT NULL REFERENCES repository_keys(id) ON DELETE RESTRICT);
CREATE TABLE project_deletions(project_id TEXT PRIMARY KEY,cache_dev INTEGER NOT NULL,cache_ino INTEGER NOT NULL,lfs_dev INTEGER NOT NULL DEFAULT 0,lfs_ino INTEGER NOT NULL DEFAULT 0,status TEXT NOT NULL,last_error TEXT NOT NULL DEFAULT '',created_at INTEGER NOT NULL,updated_at INTEGER NOT NULL,attempts INTEGER NOT NULL DEFAULT 0,retry_after INTEGER NOT NULL DEFAULT 0);
CREATE TABLE ssh_host_trust(host TEXT NOT NULL,port INTEGER NOT NULL,trusted_key BLOB,observed_key BLOB,observed_fingerprint TEXT NOT NULL DEFAULT '',warning TEXT NOT NULL DEFAULT '',PRIMARY KEY(host,port));
CREATE TABLE project_lfs_settings(project_id TEXT PRIMARY KEY REFERENCES projects(id) ON DELETE CASCADE,endpoint TEXT NOT NULL,object_origins TEXT NOT NULL,allow_internal INTEGER NOT NULL DEFAULT 0,internal_addresses TEXT NOT NULL DEFAULT '[]',updated_at INTEGER NOT NULL);
CREATE TABLE deployments(id TEXT PRIMARY KEY,project_id TEXT NOT NULL REFERENCES projects(id) ON DELETE RESTRICT,name TEXT NOT NULL,commit_id TEXT NOT NULL,generation INTEGER NOT NULL DEFAULT 1,live_commit TEXT NOT NULL DEFAULT '',live_dev INTEGER NOT NULL DEFAULT 0,live_ino INTEGER NOT NULL DEFAULT 0,status TEXT NOT NULL DEFAULT 'queued',error TEXT NOT NULL DEFAULT '',created_at INTEGER NOT NULL,updated_at INTEGER NOT NULL,target_kind TEXT NOT NULL DEFAULT 'commit',target_name TEXT NOT NULL DEFAULT '',automation_paused INTEGER NOT NULL DEFAULT 0,automation_epoch INTEGER NOT NULL DEFAULT 0,UNIQUE(project_id,name));
CREATE TABLE deployment_jobs(id TEXT PRIMARY KEY,deployment_id TEXT NOT NULL REFERENCES deployments(id) ON DELETE CASCADE,commit_id TEXT NOT NULL,generation INTEGER NOT NULL,status TEXT NOT NULL,log TEXT NOT NULL DEFAULT '',created_at INTEGER NOT NULL,updated_at INTEGER NOT NULL,force_redeploy INTEGER NOT NULL DEFAULT 0,rollback_commit TEXT NOT NULL DEFAULT '',durable INTEGER NOT NULL DEFAULT 0,retry_enqueued INTEGER NOT NULL DEFAULT 0,automatic INTEGER NOT NULL DEFAULT 0,automation_epoch INTEGER NOT NULL DEFAULT 0);
CREATE TABLE publication_intents(deployment_id TEXT PRIMARY KEY REFERENCES deployments(id) ON DELETE CASCADE,job_id TEXT NOT NULL,stage_name TEXT NOT NULL,had_old INTEGER NOT NULL,old_dev INTEGER NOT NULL,old_ino INTEGER NOT NULL,new_dev INTEGER NOT NULL,new_ino INTEGER NOT NULL,phase TEXT NOT NULL,created_at INTEGER NOT NULL);
CREATE TABLE publication_cleanup(deployment_id TEXT NOT NULL,job_id TEXT NOT NULL,path_name TEXT NOT NULL,dev INTEGER NOT NULL,ino INTEGER NOT NULL,not_before INTEGER NOT NULL,last_error TEXT NOT NULL DEFAULT '',attempts INTEGER NOT NULL DEFAULT 0,PRIMARY KEY(deployment_id,job_id));
CREATE TABLE deployment_removal_paths(deployment_id TEXT NOT NULL,path_name TEXT NOT NULL,dev INTEGER NOT NULL,ino INTEGER NOT NULL,last_error TEXT NOT NULL DEFAULT '',attempts INTEGER NOT NULL DEFAULT 0,PRIMARY KEY(deployment_id,path_name));
CREATE TABLE deployment_deletions(deployment_id TEXT PRIMARY KEY,status TEXT NOT NULL,last_error TEXT NOT NULL DEFAULT '',created_at INTEGER NOT NULL,updated_at INTEGER NOT NULL,retry_after INTEGER NOT NULL DEFAULT 0);
CREATE TABLE archived_deployment_jobs(id TEXT PRIMARY KEY,deployment_id TEXT NOT NULL,commit_id TEXT NOT NULL,generation INTEGER NOT NULL,status TEXT NOT NULL,log TEXT NOT NULL,created_at INTEGER NOT NULL,updated_at INTEGER NOT NULL);
CREATE TABLE project_webhooks(project_id TEXT PRIMARY KEY REFERENCES projects(id) ON DELETE CASCADE,secret BLOB NOT NULL,created_at INTEGER NOT NULL);
CREATE TABLE project_gitea_webhooks(project_id TEXT PRIMARY KEY REFERENCES projects(id) ON DELETE CASCADE,secret BLOB NOT NULL,created_at INTEGER NOT NULL);
CREATE TABLE webhook_deliveries(project_id TEXT NOT NULL REFERENCES projects(id) ON DELETE CASCADE,provider TEXT NOT NULL,delivery_id TEXT NOT NULL,event TEXT NOT NULL,outcome TEXT NOT NULL,created_at INTEGER NOT NULL,PRIMARY KEY(project_id,provider,delivery_id));
